(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">شاهد أيديًا حقيقية تعزف موسيقاك.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">ثم اسحبها إلى الـ DAW الخاص بك.</span>","hero.cycle":"ثم اسحبها إلى الـ DAW الخاص بك.|اقرأ كل نغمة.|تعلّم كيف تُعزف.","hero.sub":"أكوردات ولحن وخط باص ولحن مضاد، مكتوبة بأي أسلوب، تُعرض كنوتات موسيقية وتعزفها أيدٍ واقعية على آلات واقعية، من البيانو والغيتار حتى فرقة كاملة. ومعها دروس موسيقى تعلّمك أن تعزفها وتكتبها وتوزّعها بنفسك. بلا اتصال وخالٍ من الذكاء الاصطناعي بنسبة 100%.","hero.chipStandalone":"مستقل","what.title":"ما هو","what.p1":"معظم من يستخدمون مولّد أكوردات لا يرون أبدًا كيف ستُعزف أجزاؤه، ومعظم من يتعلّمون آلة موسيقية لا يرون أبدًا يدي العازف عن قرب. Handscore يريك الأمرين معًا.","what.p2":"اختر نوعًا موسيقيًا أو فنانًا أو منتجًا، فيكتب Handscore أربعة أجزاء بذلك الأسلوب: أكوردات ولحنًا وخط باص ولحنًا مضادًا. تظهر كنوتات موسيقية على حامل النوتة الخاص بالآلة، وتعزفها أيدٍ واقعية كما يعزفها عازف تلك الآلة: كل إصبع على المفتاح الذي كان عازف البيانو سيستخدمه، وكل دستان وكل ضربة على الأوتار كما كان عازف الغيتار سيفعل. تأتي البيانوهات أولًا، ثم الغيتارات وغيتار الباص، وبعدها كل عائلة من الآلات، حتى فرقة كاملة.","what.p3":"تظهر كل نغمة حيث تُعزف، ويحمل كل مفتاح بيانو اسمه على واجهته، فترى بالضبط ما الذي يُسمَع. وحين يصبح جزء ما كما تريد، اسحبه من نوتته مباشرةً إلى مسار في الـ DAW الخاص بك.","what.p4":"وهو يعلّم أيضًا. تبدأ الدروس من اليوم الأول على البيانو، فتستمع إليك وأنت تعزف وتمضي قُدمًا حين تُتقن ما تعزفه، ثم تنتقل إلى قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى، وكتابة الأغاني وكلماتها، وتوزيع الأغاني، والمزج، والعزف على الطبول بالأصابع.","inside.title":"ما سيفعله","inside.instruments.title":"كل عائلات الآلات","inside.instruments.body":"أربعة بيانوهات حقيقية أولًا، ثم الغيتارات وغيتار الباص؛ وبعدها الأورغنات، وآلات المطارق، والهارب، والوتريات التي تُعزف بالقوس، وآلات النفخ الخشبية، وآلات النفخ النحاسية، وطقم طبول، حتى فرقة كاملة، عائلةً تلو الأخرى.","inside.hands.title":"أيدٍ واقعية","inside.hands.body":"يدان تعزفان كل نغمة كما يفعل عازف تلك الآلة: بالإصبع الذي كان عازف البيانو سيختاره، وبالدستان والضربة اللذين كان عازف الغيتار سيستخدمهما.","inside.lessons.title":"دروس الموسيقى","inside.lessons.body":"دورات تمتد من نغماتك الأولى على البيانو إلى قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى، وكتابة الأغاني وكلماتها، وتوزيع الأغاني، والمزج. تستمع إليك وأنت تعزف، وتقرأ لك كل درس حين تفعّل «القراءة بصوت عالٍ».","inside.drums.title":"العزف على الطبول بالأصابع","inside.drums.body":"أنماط طبول تُولَّد أو تُعزف وتُسجَّل على وحدة تحكم ذات وسادات تضيء مع كل ضربة، ودورة من أول إيقاع حتى الإيقاعات الكاملة.","inside.sheets.title":"أربع نوتات موسيقية","inside.sheets.body":"الأكوردات واللحن واللحن المضاد والباص، كلٌّ على نوتته الخاصة، وتضيء كل نغمة لحظة عزفها.","inside.styles.title":"كل أسلوب يعرفه Freally MIDI Master","inside.styles.body":"73 نوعًا موسيقيًا و1507 فنانين و833 منتجًا، من المولّدات نفسها القائمة على القواعد.","inside.drag.title":"اسحب ملف MIDI","inside.drag.body":"جزء واحد في كل مرة أو الأجزاء الأربعة معًا، تُسحب من النوتات مباشرةً إلى الـ DAW الخاص بك، أو تُحفظ كملف MIDI أو كملف PDF للنوتات.","inside.views.title":"عرض أمامي وعلوي وجانبي","inside.views.body":"بدّل بينها بينما تُعزف الموسيقى؛ تدور النوتات لتبقى مقروءة ولا تفوّت الأيدي أي نغمة.","inside.daw.title":"في أي DAW","inside.daw.body":"CLAP وVST3 وAU، إضافةً إلى تطبيق مستقل. Windows وmacOS وLinux.","inside.offline.title":"بلا اتصال، بلا ذكاء اصطناعي","inside.offline.body":"لا حساب، لا قياس عن بُعد، لا شبكة، لا نموذج. كل جزء وكل توزيع للأصابع وكل حركة يأتي من قواعد، تفرضها بوابة بناء لا مجرد وعد بها.","ladder.title":"الطريق إلى 1.0، ثم إلى 2.0","ladder.intro":"سطر واحد لكل إصدار. تأتي الدروس والعزف على الطبول بالأصابع والغيتارات وغيتار الباص قبل 1.0. وبعده، يجلب كل إصدار عائلة جديدة من الآلات، تعزفها أيدٍ واقعية بالطريقة التي سيريك بها معلّم.","ladder.rung.v0.1.0":"الأساس: يُحمَّل المكوّن الإضافي بصيغ CLAP وVST3 وAU وكتطبيق مستقل، ويطلب منك قبول ترخيصه، ويُفتح على لوحة مفاتيح من 88 مفتاحًا لكلٍّ منها اسمه.","ladder.rung.v0.2.0":"البيانوهات الحقيقية: الكبير والأكوستيك والقائم والهونكي تونك، تتحرك مفاتيحها وتصدر أصواتها أثناء العزف.","ladder.rung.v0.3.0":"أيدٍ واقعية على لوحة المفاتيح، تعزف كل نغمة بالأصابع التي كان عازف البيانو سيختارها، مع اثنتين وستين قطعة كلاسيكية من الملكية العامة للتعلّم وشريط تشغيل للتنقّل فيها وأنت تسمعها.","ladder.rung.v0.4.0":"ولّد بأي أسلوب، واقرأ النوتات الأربع وهي تضيء، واسحب ملف MIDI إلى الـ DAW الخاص بك.","ladder.rung.v0.5.0":"العرضان العلوي والجانبي، مع النوتات ممدّدة على البيانو، وانتقال سلس بين العروض.","ladder.rung.lessons-1":"دروس من اليوم الأول: دورة بيانو تستمع إليك وأنت تعزف وتمضي قُدمًا حين تُتقن ما تعزفه، ومفتاح «القراءة بصوت عالٍ» الذي يقرأ لك كل درس، وتضيء كل كلمة لحظة نطقها.","ladder.rung.mixer":"ميكسر لكل جزء، مع الفيدرات والبان والـ EQ والمؤثرات والضغط الديناميكي، ويبقى المزج محفوظًا عند السحب.","ladder.rung.song-view":"عرض الأغنية: ابنِ أغنية كاملة يدويًا من مقاطعها، أو ابدأ من توزيع فنان أو نوع موسيقي، ثم شاهدها تُعزف واسحبها إلى الـ DAW الخاص بك.","ladder.rung.lessons-2":"مزيد من الدورات: قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى بنظام Nashville Number System، وكتابة الأغاني وكلماتها، والتوزيع، والمزج.","ladder.rung.finger-drumming":"العزف على الطبول بالأصابع على وحدة تحكم ذات وسادات تضيء مع كل ضربة، من أول إيقاع حتى الإيقاعات الكاملة.","ladder.rung.live-listening":"الاستماع المباشر: اعزف على آلة حقيقية عبر ميكروفون أو كابل آلة موسيقية، فتسمعك الدروس.","ladder.rung.guitars":"الغيتارات: الأكوستيك والنايلون والكهربائي والمكتوم، مع ضغط حقيقي على الدساتين ونقر وضرب على الأوتار.","ladder.rung.bass":"غيتار الباص، يُعزف بالأصابع وبأسلوب السلاب.","ladder.rung.own-audio":"ملفات الصوت وMIDI الخاصة بك، تُقرأ إلى أجزاء وتعزفها الأيدي.","ladder.rung.classics":"الكلاسيكيات: ألحان من الملكية العامة للمشاهدة والاستماع.","ladder.rung.realism":"مرحلة الواقعية: الإضاءة والخامات والحركة مُقاسة على عزف مصوَّر.","ladder.rung.finish":"اللمسات الأخيرة: الإعدادات، وثماني عشرة لغة في كل مكان، وإمكانية الوصول، والدليل.","ladder.rung.v1.0.0-beta.1":"إشعارات التحديث والإصداران التجريبي والمدفوع.","ladder.rung.v1.0.0":"الإصدار العام الأول.","ladder.rung.v1.1.0":"البيانوهات الكهربائية والأورغنات، والأورغنات بلوحة دواسات لخط الباص.","ladder.rung.v1.2.0":"الهاربسيكورد والكلافينيت والسيليستا وبيانو الألعاب؛ والأوكوليلي والبانجو والماندولين.","ladder.rung.v1.3.0":"آلات المطارق: الزيلوفون والماريمبا والفيبرافون والغلوكنشبيل.","ladder.rung.v1.4.0":"الهارب والكوتو والسيتار والدولسيمر الجبلي.","ladder.rung.v1.5.0":"الكمان والفيولا والتشيلو والكونترباص، بالقوس وبالنقر.","ladder.rung.v1.6.0":"الفلوت والكلارينيت والساكسفونات والأوبوا والريكوردر.","ladder.rung.v1.7.0":"الترومبيت والترومبون والهورن الفرنسي والتوبا.","ladder.rung.v1.8.0":"طقم طبول مُجهَّز ومعزوف بالطريقة التي يتبعها عازف طبول محترف.","ladder.rung.v1.9.0":"وضع العزف المصاحب والتعلّم.","ladder.rung.v2.0.0":"الفرقة: كل جزء على آلته الخاصة، ولكل آلة عازفها.","ladder.note":"الإصدار المكتمل مبنيّ ومُوسوم. إنه ليس تنزيلًا: لا توجد أي تنزيلات قبل 1.0.0.","honest.title":"أين هو اليوم","honest.start.title":"لا يزال في بدايته الأولى","honest.start.body":"يُحمَّل الإصدار 0.3.0 في DAW ويُفتح على أربعة بيانوهات حقيقية تعزفها أيدٍ واقعية، مع اثنتين وستين قطعة كلاسيكية من الملكية العامة للتعلّم، وشريط تشغيل لإيقافها مؤقتًا وترجيعها والتنقّل فيها وأنت تسمعها. البيانوهات تأتي أولًا: أما توليد أجزائك الخاصة والنوتات والدروس وكل آلة أخرى فتصل إصدارًا بعد إصدار، كما يبيّن السلّم أعلاه.","honest.downloads.title":"لا توجد تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية على هذه الصفحة، ولا بناء مسبق، ولا وصول مبكر.","honest.network.title":"لا يتصل بالإنترنت أبدًا","honest.network.body":"لا يحتوي المكوّن الإضافي ولا التطبيق المستقل على أي شيفرة شبكة، وتفشل بوابة بناء إذا أُضيفت أي شيفرة من هذا القبيل. قد يضيف إصدار لاحق فحص تحديثات يبقى مطفأً ما لم تُفعّله بنفسك، ويشغّله برنامج منفصل.","site.tagline":"شاهد أيديًا حقيقية تعزف موسيقاك. ثم اسحبها إلى الـ DAW الخاص بك.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © 2026 Mike Weaver، الذي يمارس نشاطه التجاري باسم Havoc Software. ليس مفتوح المصدر.","footer.yours":"ملفات MIDI التي تولّدها وتسحبها إلى الـ DAW الخاص بك ملك لك. لا يدّعي مؤلف Handscore أي ملكية لها.","featuresPage.lead":"أربعة أجزاء مكتوبة بأي أسلوب، تُعرض كنوتات موسيقية وتعزفها أيدٍ واقعية على آلات واقعية، وكل جزء يُسحب مباشرةً إلى الـ DAW الخاص بك، ودروس موسيقى تعلّمك أن تعزفها وتكتبها وتوزّعها بنفسك.","featuresPage.version":"تصف هذه الصفحة ما سيفعله الإصدار 1.0 من Freally Handscore. الإصدار الحالي هو 0.3.0: اطّلع على الطريق إلى 1.0 في الصفحة الرئيسية.","featuresPage.numbers.parts":"أجزاء: الأكوردات واللحن واللحن المضاد والباص","featuresPage.numbers.genres":"نوعًا موسيقيًا","featuresPage.numbers.artists":"فنانين","featuresPage.numbers.producers":"منتجًا","featuresPage.numbers.keys":"مفتاحًا، لكلٍّ منها اسمه على واجهته","featuresPage.numbers.plugins":"صيغ مكوّنات إضافية، إضافةً إلى تطبيق مستقل","featuresPage.numbers.languages":"لغة","featuresPage.numbers.ai":"نماذج ذكاء اصطناعي","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"Handscore مجاني اليوم: لا فئة مدفوعة، ولا اشتراك، ولا حساب. لا يوجد شيء لتنزيله بعد، لأنه لا توجد تنزيلات قبل الإصدار 1.0.0، وقد تُباع الإصدارات اللاحقة.","featuresPage.cards.title":"ما يفعله الإصدار 1.0","featuresPage.cards.pianos.title":"أربعة بيانوهات حقيقية","featuresPage.cards.pianos.body":"بيانو كبير وبيانو أكوستيك وبيانو قائم وبيانو هونكي تونك، كلٌّ منها تتحرك مفاتيحه مع صدور أصواتها، ويُعزف بأصوات البيانو المقيسة نفسها التي يستخدمها Freally MIDI Master.","featuresPage.cards.strings.title":"الغيتارات وغيتار الباص","featuresPage.cards.strings.body":"غيتارات أكوستيك ونايلون وكهربائية ومكتومة، بضغط حقيقي على الدساتين ونقر وضرب على الأوتار، وغيتار الباص، يُعزف بالأصابع وبأسلوب السلاب.","featuresPage.cards.hands.title":"أيدٍ واقعية","featuresPage.cards.hands.body":"يدان تعزفان كل نغمة كما يفعل العازف: بالإصبع الذي كان عازف البيانو سيختاره، وبالدستان والضربة اللذين كان عازف الغيتار سيستخدمهما.","featuresPage.cards.sheets.title":"أربع نوتات موسيقية","featuresPage.cards.sheets.body":"الأكوردات واللحن واللحن المضاد والباص، كلٌّ على نوتته الخاصة، وتضيء كل نغمة لحظة عزفها.","featuresPage.cards.styles.title":"كل أسلوب يعرفه Freally MIDI Master","featuresPage.cards.styles.body":"اختر من بين 73 نوعًا موسيقيًا أو 1507 فنانين أو 833 منتجًا، فتكتب المولّدات نفسها القائمة على القواعد الأجزاء الأربعة بذلك الأسلوب.","featuresPage.cards.yours.title":"ملفات الصوت وMIDI الخاصة بك","featuresPage.cards.yours.body":"أحضر ملفات الصوت أو MIDI الخاصة بك، فيقرؤها Handscore إلى أجزاء تعزفها الأيدي.","featuresPage.cards.classics.title":"الكلاسيكيات","featuresPage.cards.classics.body":"أغانٍ من الملكية العامة للتعلّم، من أغاني الأطفال وتراتيل الميلاد إلى الأناشيد والألحان الكلاسيكية، كلٌّ منها موزّعة لليدين وتعزفها اليدان على المسرح. ولا يمكن أن يغادر Handscore منها سوى أكورداتها.","featuresPage.cards.lessons.title":"دروس الموسيقى","featuresPage.cards.lessons.body":"دورة بيانو من اليوم الأول تستمع إليك وأنت تعزف وتمضي قُدمًا حين تُتقن ما تعزفه، ثم دورات في قراءة النوتة الموسيقية، والإيقاع، وتدريب الأذن، ونظرية الموسيقى، وكتابة الأغاني وكلماتها، وتوزيع الأغاني، والمزج. فعّل «القراءة بصوت عالٍ» فيُقرأ لك كل درس، وتضيء كل كلمة لحظة نطقها؛ وتسمع الدورات اللاحقة آلة حقيقية عبر ميكروفون أو كابل.","featuresPage.cards.drums.title":"العزف على الطبول بالأصابع","featuresPage.cards.drums.body":"وحدة تحكم ذات وسادات تعزف عليها أيدٍ واقعية، وتضيء كل وسادة لحظة ضربها. ولّد نمط طبول أو اعزف نمطك الخاص وسجّله، وكرّره وأضف إليه، وتعلّم من أول إيقاع حتى الإيقاعات الكاملة.","featuresPage.cards.songs.title":"أغانٍ كاملة وميكسر","featuresPage.cards.songs.body":"ابنِ أغنية يدويًا من مقاطعها أو ابدأ من توزيع فنان، ثم امزج كل جزء على قناته الخاصة، واسحبها إلى الخارج والمزج محفوظ فيها.","featuresPage.cards.drag.title":"اسحب ملف MIDI","featuresPage.cards.drag.body":"جزء واحد في كل مرة أو الأجزاء الأربعة معًا، تُسحب من النوتات مباشرةً إلى الـ DAW الخاص بك، أو تُحفظ كملف MIDI أو كملف PDF للنوتات.","featuresPage.cards.views.title":"عرض أمامي وعلوي وجانبي","featuresPage.cards.views.body":"بدّل بينها بينما تُعزف الموسيقى؛ تدور النوتات لتبقى مقروءة ولا تفوّت الأيدي أي نغمة.","featuresPage.cards.daw.title":"في أي DAW","featuresPage.cards.daw.body":"CLAP وVST3 على Windows وmacOS وLinux، وAU على macOS، وتطبيق مستقل للعمل بلا DAW.","featuresPage.cards.offline.title":"بلا اتصال، بلا ذكاء اصطناعي","featuresPage.cards.offline.body":"لا حساب، ولا قياس عن بُعد، ولا شبكة، ولا نموذج. كل جزء وكل توزيع للأصابع وكل حركة يأتي من قواعد.","featuresPage.compare.title":"جنبًا إلى جنب","featuresPage.compare.intro":"Freally Handscore 1.0 بجانب الأدوات التي يستخدمها الناس لكتابة الأجزاء الموسيقية أو لمشاهدة عزف البيانو. خانات المنتجات الأخرى مأخوذة من صفحاتها العامة ومن المراجعات، وقد رُوجعت في أكتوبر 2026؛ وحيث لم نتمكن من تأكيد أمر ما، تقول الخانة ذلك.","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.generate":"يكتب أكوردات وألحانًا وخطوط باص جديدة بأساليب محددة بالاسم","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.row.plugin":"يعمل داخل الـ DAW الخاص بك كمكوّن إضافي","featuresPage.compare.row.hands":"يعرض أيديًا واقعية ثلاثية الأبعاد تعزف النغمات","featuresPage.compare.note.library":"مكتبته الخاصة من المقطوعات","featuresPage.compare.legend.part":"جزئيًا","featuresPage.compare.note.fingers":"أرقام الأصابع، بلا أيدٍ","featuresPage.compare.row.sheets":"يعرض النغمات كنوتة موسيقية","featuresPage.compare.legend.unknown":"غير مؤكَّد","featuresPage.compare.row.drag":"يسحب ملفات MIDI إلى الـ DAW الخاص بك","featuresPage.compare.row.offline":"يعمل بلا اتصال، وبلا ذكاء اصطناعي","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"من بين هذه الأربعة، وحده Handscore 1.0 يملك كل الصفوف: أجزاء مكتوبة بأساليب محددة بالاسم، وأيدٍ واقعية تعزفها، والنوتة الموسيقية، والسحب إلى الـ DAW الخاص بك، والمكوّن الإضافي.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"Scaler 3 محطة عمل لنظرية الموسيقى أوسع بكثير. وSynthesia مصمَّم لتعلّم المقطوعات على لوحة مفاتيحك الخاصة؛ أما دروس Handscore فتستمع إليك وأنت تعزف بدءًا من الإصدار 0.6، لكن العزف المصاحب المباشر ينتظر الإصدار 1.9. ويضع AR Pianist عازفه في غرفتك بالواقع المعزَّز، وهو ما لا يفعله Handscore.","featuresPage.compare.fineprint":"Scaler وAR Pianist وSynthesia علامات تجارية لمالكيها، وهم غير مرتبطين بـ Freally Handscore. أخبرنا إن كانت خانة ما خاطئة وسنصحّحها.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.rules.title":"قواعد لا نموذج","featuresPage.why.rules.body":"كل جزء وكل توزيع للأصابع وكل حركة يأتي من قواعد، بلا أي نموذج في أي مكان. الأسلوب نفسه والبذرة نفسها تعطي الأجزاء نفسها، في كل مرة.","featuresPage.why.drag.title":"ما تراه هو ما تسحبه","featuresPage.why.drag.body":"تُرسم النوتات من ملف MIDI الذي تسحبه، وتعزف الأيدي تلك النغمات بالضبط، لذا فما يصل إلى مسارك هو ما شاهدته.","featuresPage.why.real.title":"مبني بمقاسات حقيقية","featuresPage.why.real.body":"كل آلة مبنية بمقاساتها الحقيقية: لوحة المفاتيح بحجم بيانو حقيقي، وكل مفتاح يدور على نقطة ارتكازه كما يفعل المفتاح الحقيقي.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا حساب ولا قياس عن بُعد ولا سحابة. لا يتصل المكوّن الإضافي ولا التطبيق المستقل بالإنترنت أبدًا، وتفشل بوابة بناء إذا أُضيفت يومًا شيفرة شبكة.","featuresPage.coming.title":"ما الذي لم يأتِ بعد","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة ميزات تخفي ثغراتها لا تستحق القراءة. تصف هذه الصفحة الإصدار 1.0، ويُبنى Handscore إصدارًا بعد إصدار، لذا فمعظم ما فيها لم يُبنَ بعد. كل إصدار على الطريق إلى 1.0 موسوم بحالته.","featuresPage.limits.title":"ما لا يفعله الإصدار 1.0","featuresPage.limits.export":"الأغنية التي يطابق لحنُها إحدى الكلاسيكيات أو لحنًا معروفًا لا يغادر منها Handscore سوى أكورداتها.","featuresPage.limits.families":"يعزف البيانوهات والغيتارات وغيتار الباص. وكل عائلة أخرى من الآلات تصل إصدارًا بعد إصدار بعد 1.0، حتى الفرقة الكاملة في 2.0.","featuresPage.limits.learn":"تستمع دروسه إليك وأنت تعزف، لكن الأيدي لا تتبعك مباشرةً بعد: العزف المصاحب على أي آلة يصل في الإصدار 1.9.","featuresPage.coming.downloads":"لا توجد تنزيلات قبل الإصدار 1.0، ولا شيء منها على هذه الصفحة.","docs.intro":"ينمو Handscore ليصبح أيديًا واقعية على كل عائلة من الآلات، مع دروس موسيقى من البيانو إلى العزف على الطبول بالأصابع وكتابة الأغاني وتوزيعها. وينمو هذا الدليل معه، إصدارًا بعد إصدار. يغطي الآن ما يفعله الإصدار 0.3.0: البيانوهات، واليدان، والكلاسيكيات، وشريط التشغيل.","docs.start.title":"البدء","docs.agreement.title":"اتفاقية الترخيص","docs.stage.title":"المسرح","docs.pianos.title":"البيانوهات","docs.play.title":"العزف على المفاتيح","docs.hands.title":"اليدان","docs.classics.title":"الكلاسيكيات","docs.transport.title":"شريط التشغيل","docs.theme.title":"الوضعان الفاتح والداكن","docs.language.title":"اللغات","docs.privacy.title":"خصوصيتك","docs.start.p1":"يعمل Handscore داخل الـ DAW الخاص بك كآلة موسيقية من نوع CLAP أو VST3 أو AU، أو بمفرده كتطبيق مستقل. ضعه على مسار آلة موسيقية.","docs.start.p2":"لا توجد تنزيلات قبل الإصدار 1.0.0، والشيفرة المصدرية خاصة.","docs.agreement.p1":"عند فتح Handscore لأول مرة، يعرض اتفاقية الترخيص الخاصة به. وحتى تختار «أوافق»، لا يفعل Handscore شيئًا ولا يُصدر أي صوت.","docs.agreement.p2":"تُحفظ إجابتك على جهازك وتشترك فيها كل نسخة مفتوحة من Handscore، في كل DAW وفي التطبيق المستقل. إذا رفضت، تبقى الاتفاقية على الشاشة، جاهزةً متى وافقت.","docs.stage.p1":"أسفل الشريط العلوي يقع المسرح: البيانو الذي اخترته بمفاتيحه الـ88، من A0 إلى C8، بمقاسات بيانو حقيقي، يملأ عرض النافذة. اسم كل مفتاح مكتوب على واجهته — على المفاتيح البيضاء بحبر داكن، وعلى السوداء بالأبيض — ويختفي ما دام المفتاح مضغوطًا، فترى دائمًا أي النغمات تُعزف.","docs.stage.p2":"إذا لم يستطع جهازك الرسم بالأبعاد الثلاثية، يقول المسرح ذلك ويشرح كيفية تفعيله، بدلًا من ألا يعرض شيئًا.","docs.stage.p3":"يقيس Handscore مدى سرعة جهازك في رسم المسرح، ويستقر على الجودة التي يستطيع الحفاظ عليها بسلاسة.","docs.pianos.p1":"يعتلي المسرحَ واحدٌ من أربعة بيانوهات في كل مرة: Grand Piano وAcoustic Piano وUpright Piano وHonky-Tonk Piano، لكلٍّ منها شكله وطلاؤه وصوته.","docs.pianos.p2":"يفتح زر «اختر الوضع» أعلى اليمين (أو P) خياراتك حسب الفئة. ضمن «الآلات»، يعزف زر «معاينة» جملة قصيرة على بيانو دون التبديل إليه، ويضعه زر «اختيار» على المسرح بانتقال تدريجي من البيانو السابق. يُحفظ اختيارك مع مشروعك.","docs.play.p1":"انقر على مفتاح لتسمعه، أو مرّر المؤشر فوق المفاتيح لتعزفها واحدًا تلو الآخر. ينخفض كل مفتاح دائرًا على نقطة ارتكازه، وكلما عُزف بقوة أكبر كان أسرع، ويخفت اسمه ما دام منخفضًا ثم يعود حين يرتفع.","docs.play.p2":"يعزف MIDI القادم من DAW لديك على البيانو ويحرّك مفاتيحه. وتُبقي دواسة الاستدامة النغمات التي تتركها حتى ترفع قدمك عنها.","docs.hands.p1":"تعزف يدان واقعيتان كل نغمة على المسرح كما يفعل عازف البيانو: كل إصبع مختار للمقطع، والإبهام يمرّ من تحت اليد في السلّم الموسيقي، والأكوردات الواسعة تُطال، وترتفع يدٌ فوق الأخرى حين تتطلّب الموسيقى تقاطع اليدين. وحين لا يُعزف شيء، تستريحان على المفاتيح متأهبتين.","docs.hands.p2":"يحدّد Handscore أي يد تعزف كل نغمة، وبأي إصبع، قبل أن تُعزف الموسيقى، فتصل اليدان لحظة انخفاض المفاتيح.","docs.classics.p1":"تضم «الكلاسيكيات» في «اختر الوضع» اثنتين وستين أغنية من الملكية العامة للتعلّم: أغاني أطفال، وأغاني عيد الميلاد وتراتيله، وأغانٍ شعبية، وترانيم روحية وأناشيد، وألحانًا كلاسيكية، ومقطوعات بيانو محبوبة. كلٌّ منها موزّعة لليدين، اللحن في اليمنى والأكوردات في اليسرى. ابحث بالعنوان أو المؤلف، ثم اختر «تشغيل».","docs.transport.p1":"أسفل المسرح: الترجيع، والتشغيل أو الإيقاف المؤقت، والإيقاف، والتقديم السريع، وخط زمني يعرض زمن الأغنية وعلامة عند كل مازورة. مرّر المؤشر فوق الخط الزمني لترى اليدين في تلك اللحظة في معاينة صغيرة؛ وانقر أو اسحب للانتقال إليها. اضغط مطوّلًا على الترجيع أو التقديم السريع للتنقّل بسرعة. وفي الحالتين تسمع كل نغمة تمرّ بها. يشغّل مفتاح المسافة ويوقف مؤقتًا، وتنقلك مفاتيح الأسهم على الخط الزمني مازورةً واحدة.","docs.transport.p2":"حرف M بجانب المفاتيح هو المترونوم. شغّله فتحدّد نقرةٌ كل نبضة، والأولى من كل مازورة أعلى، بينما تُظهر نقطتاه النبضة.","docs.theme.p1":"مفتاح «السمة الداكنة» أعلى اليسار يجعل النافذة فاتحة أو داكنة. يتذكّر Handscore اختيارك، وكذلك تفعل تطبيقات Freally الأخرى على جهازك.","docs.language.p1":"يتحدث Handscore ثماني عشرة لغة ويبدأ بلغة نظامك.","docs.privacy.p1":"لا يستخدم المكوّن الإضافي ولا التطبيق المستقل الشبكة أبدًا. إذا توقّف Handscore يومًا على نحو غير متوقع، يُحفظ تقرير قصير على جهازك ويُعرض عليك في المرة التالية التي يُفتح فيها؛ ولا يُرسَل شيء ما لم تختر الإبلاغ عنه.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.3.0 منجز · v0.4.0 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Handscore مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.ladder.later":"لاحقًا","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">عشرة تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Handscore، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v0.3.0","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.numbers.lead":"كل رقم محسوب من التطبيق نفسه. لا شيء مُقدَّر، ولا شيء مُقرَّب إلى الأعلى.","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.later":"بعد ذلك، ولم يُجدوَل بعد","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Handscore، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.1dca7b1d60db":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.d35d794c003e":"الأيدي الواقعية. تعزف الآن يدان على البيانو فوق مسرح Handscore كما يفعل عازف البيانو — كل إصبع مختار للمقطع، والإبهام يمرّ من تحت اليد في السلّم الموسيقي، وترتفع يدٌ فوق الأخرى حين تتطلّب الموسيقى تقاطع اليدين. اثنتان وستون قطعة كلاسيكية من الملكية العامة جاهزة للتعلّم، من Mary Had a Little Lamb إلى Silent Night وThe Star-Spangled Banner، ويتيح لك شريط التشغيل أسفل المسرح الإيقاف المؤقت والترجيع والتقديم السريع أو السحب إلى أي لحظة، وأنت تسمع النغمات في أثناء ذلك.","changelog.6b02e0d363a4":"الإضافات","changelog.0390e4a43a0a":"<strong>أيدٍ واقعية على لوحة المفاتيح.</strong> يدان تنتهيان عند الرسغ تعزفان كل نغمة على البيانوهات الأربعة جميعها: كل إصبع مختار كما يختاره عازف البيانو، والإبهام يمرّ من تحت اليد في السلالم الموسيقية، والأكوردات الواسعة تُطال، والإبهام مستلقٍ على جانبه ومنحنٍ برفق، وترتفع يدٌ فوق الأخرى لتتقاطعا. وحين لا يُعزف شيء، تستريحان على المفاتيح متأهبتين.","changelog.2c009dbabcfe":"<strong>توزيع الأصابع محسوم قبل أن تصدر أي نغمة.</strong> يقرّر Handscore أي يد تعزف كل نغمة وبأي إصبع قبل أن تُعزف الموسيقى، فتصل اليدان لحظة انخفاض المفاتيح لا بعدها.","changelog.216f61cb53a3":"<strong>اختر الوضع.</strong> صار الزر أعلى اليمين (أو P) يحمل عبارة <em>اختر الوضع</em>، ويفتح خياراتك حسب الفئة: الآلات، والكلاسيكيات، ومقاطع، والدروس (تصل في إصدار لاحق).","changelog.44952a5f65fd":"<strong>اثنتان وستون قطعة كلاسيكية للتعلّم.</strong> أغاني أطفال، وأغاني عيد الميلاد وتراتيله، وأغانٍ شعبية، وترانيم روحية وأناشيد، وألحان كلاسيكية، ومقطوعات بيانو محبوبة — Chopsticks وJingle Bells وSilent Night و«نشيد الفرح» وFür Elise وThe Entertainer وThe Star-Spangled Banner وغيرها — كلٌّ منها موزّعة لليدين، اللحن في اليمنى والأكوردات في اليسرى. ابحث عنها بالعنوان أو المؤلف. وجميعها من الملكية العامة.","changelog.d8fc29c977d3":"<strong>مقاطع للمشاهدة.</strong> سلّم موسيقي، وii–V–I، وأربيجيو، وتقاطع لليدين، كلٌّ منها نظرة سريعة على اليدين وهما تعملان.","changelog.d0ff9a5e5f3f":"<strong>شريط التشغيل.</strong> التشغيل والإيقاف المؤقت والإيقاف والترجيع والتقديم السريع أسفل المسرح، مع خط زمني يعرض زمن الأغنية ومازوراتها. مرّر المؤشر فوق الخط الزمني لترى اليدين في تلك اللحظة في معاينة صغيرة. اسحب على امتداده، أو اضغط مطوّلًا على الترجيع أو التقديم السريع، فتسمع كل نغمة تمرّ بها، في كلا الاتجاهين.","changelog.197a823169eb":"<strong>مترونوم.</strong> شغّله فتحدّد نقرةٌ كل نبضة، والأولى من كل مازورة أعلى، بينما تُظهر النقاط بجانب حرف <em>M</em> النبضة.","changelog.f94e5b4b235f":"<strong>مفتاح المسافة يشغّل ويوقف مؤقتًا.</strong>","changelog.2a6141e43be0":"التغييرات","changelog.dd397e7c80b2":"<strong>صار زر الآلة الآن «اختر الوضع»</strong>، ويُعلَّم البيانو الذي تختاره بين الآلات بعبارة <em>الحالية</em>.","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"البيانوهات الحقيقية. تقف الآن أربعة بيانوهات على مسرح Handscore — بيانو كبير للحفلات، وبيانو كبير للصالون، وبيانو قائم للاستوديو، وبيانو قائم قديم من حانات الغرب — كلٌّ منها مُضاء كما في الاستوديو، ولكلٍّ منها صوته الخاص. انقر على مفتاح أو اعزف من DAW لديك فيعزف البيانو: ينخفض المفتاح، ويخفت اسمه، وتُبقي دواسة الاستدامة ما تتركه من نغمات. ويتيح لك منتقي البيانو أن تسمع البيانو قبل أن تختاره.","changelog.a8f76e859570":"<strong>أربعة بيانوهات حقيقية.</strong> Grand Piano وAcoustic Piano وUpright Piano وHonky-Tonk Piano، لكلٍّ منها شكله وطلاؤه وصوته، في كلتا السمتين.","changelog.6f544a8bd67f":"<strong>اعزف على المفاتيح.</strong> انقر على مفتاح لتسمعه، أو مرّر المؤشر فوق المفاتيح لتعزفها واحدًا تلو الآخر. يعزف MIDI القادم من DAW لديك على البيانو ويحرّك مفاتيحه، وتُبقي دواسة الاستدامة النغمات التي تتركها حتى ترفع قدمك عنها.","changelog.3f265130a08f":"<strong>مفاتيح تتحرك كمفاتيح البيانو.</strong> ينخفض كل مفتاح دائرًا على نقطة ارتكازه، وكلما عُزف بقوة أكبر كان أسرع، ويخفت اسمه ما دام منخفضًا ثم يعود حين يرتفع.","changelog.7fd2c1ed940d":"<strong>منتقي البيانو.</strong> يفتح زر الآلة أعلى اليمين (أو P) أربع بطاقات. يعزف زر <em>معاينة</em> جملة قصيرة على ذلك البيانو دون التبديل إليه؛ ويضعه زر <em>اختيار</em> على المسرح بانتقال تدريجي من البيانو السابق. يُحفظ اختيارك مع مشروعك.","changelog.72aa386a33ff":"<strong>جودة تناسب جهازك.</strong> يقيس Handscore مدى سرعة جهازك في رسم المسرح، ويستقر على الجودة التي يستطيع الحفاظ عليها بسلاسة.","changelog.1246fc93bca0":"الإصلاحات","changelog.58e041aeca75":"<strong>المفاتيح تواكب حتى على جهاز مشغول.</strong> المفتاح الذي كان يُعزف بينما يتباطأ الجهاز في الرسم قد يبقى مرفوعًا، أو يبقى اسمه خافتًا إلى النصف؛ أما الآن فينتهي دائمًا حيث تركه عزفك.","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"الأساس. يُحمَّل Freally Handscore كمكوّن إضافي بصيغتي CLAP وVST3 وكتطبيق مستقل، ويطلب منك قبول ترخيصه، ويُفتح على مسرحه: لوحة مفاتيح من 88 مفتاحًا بمقاسات بيانو حقيقي، اسم كل مفتاح مكتوب على واجهته. لا يُولَّد شيء بعد — فذلك يصل مع البيانوهات الحقيقية والأيدي.","changelog.37cee751dc57":"<strong>المكوّن الإضافي والتطبيق المستقل.</strong> CLAP وVST3 على Windows (ويُبنى AU على جهاز Mac)، وتطبيق مستقل يحمل أيقونة Handscore في شريط عنوانه وفي شريط المهام.","changelog.bf0d03d43bfd":"<strong>اتفاقية الترخيص أولًا.</strong> حتى توافق، لا يفعل Handscore شيئًا. تُحفظ إجابتك على جهازك وتشترك فيها كل نسخة مفتوحة، في كل DAW وفي التطبيق المستقل.","changelog.28bc52fb055e":"<strong>المسرح.</strong> لوحة مفاتيح من 88 مفتاحًا، من A0 إلى C8، بمقاسات بيانو حقيقي، تملأ عرض النافذة. اسم كل مفتاح مكتوب على واجهته — على المفاتيح البيضاء بحبر داكن، وعلى السوداء بالأبيض — ويختفي ما دام المفتاح مضغوطًا.","changelog.d51fdbedfc0e":"<strong>الوضعان الفاتح والداكن.</strong> المفتاح أعلى اليسار؛ ويتذكّر Handscore اختيارك.","changelog.9e0609310c1a":"<strong>ثماني عشرة لغة.</strong> يبدأ Handscore بلغة نظامك.","changelog.f1cf7c9dfaa8":"<strong>عرض ثلاثي الأبعاد يقول متى لا يستطيع الرسم.</strong> النافذة التي تفتقر إلى WebGL 2 تشرح كيفية تفعيله بدلًا من ألا تعرض شيئًا.","changelog.0fe089d138d3":"<strong>الأعطال تُحفظ ولا تُرسَل أبدًا.</strong> إذا توقّف Handscore يومًا على نحو غير متوقع، يُحفظ تقرير قصير على جهازك للتشغيل التالي. لا يغادر شيء جهازك ما لم تختر الإبلاغ عنه."};
